    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and '0' <= s[j] <= '9':
            j += 1
        if j == i:
            raise ValueError('missing run length')
        length = int(s[i:j])
        if length <= 0:
            raise ValueError('run length must be positive')
        if j >= n:
            raise ValueError('dangling length')
        c = s[j]
        if not (('a' <= c <= 'z') or ('A' <= c <= 'Z')):
