def isbn13_valid(s):
    if not isinstance(s, str):
        return False
    t = s.replace(' ', '').replace('-', '')
    if len(t) != 13:
        return False
    total = 0
    for i, c in enumerate(t):
        if not ('0' <= c <= '9'):
            return False
        total += (i % 2 == 0) * 1 * (ord(c) - 48) + (i % 2 == 1) * 3 * (ord(c) - 48)
    return total % 10 == 0
