def parse_ini(text):
    sections = {}
    current = ""
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']') and len(line) >= 2:
            current = line[1:-1].strip()
            sections.setdefault(current, {})
            continue
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError("Invalid key in line: %r" % raw_line)
            sections.setdefault(current, {})[key] = value
            continue
        raise ValueError("Invalid line: %r" % raw_line)
    return sections
